input.new_string:
/// Returns `true` if `s` reads the same forwards and backwards, ignoring
/// spaces, case, and punctuation.
///
/// Only alphanumeric characters are considered; everything else is skipped.
pub fn is_palindrome(s: &str) -> bool {
    let normalized: Vec<char> = s
        .chars()
        .filter(|c| c.is_alphanumeric())
        .flat_map(|c| c.to_lowercase())
        .collect();

    normalized.iter().eq(normalized.iter().rev())
}

input.command:
cat > <tmp> <<'EOF'
function is_pal(s,   n, t, i, a, b) {
    n = 0; t = ""
    for (i = 1; i <= length(s); i++) {
        c = substr(s, i, 1)
        if (c ~ /[[:alnum:]]/) t = t tolower(c)
    }
    n = length(t)
    for (i = 1; i <= int(n/2); i++) {
        a = substr(t, i, 1); b = substr(t, n - i + 1, 1)
        if (a != b) { printf "%-32s norm=%-22s -> FALSE\n", "\"" s "\"", (t == "" ? "(empty)" : t); return 0 }
    }
    printf "%-32s norm=%-22s -> TRUE\n", "\"" s "\"", (t == "" ? "(empty)" : t)
    return 1
}
BEGIN {
    split("racecar|A man a plan a canal Panama|hello|Rats live on no evil star|Was it a car or a cat I saw?|No 'x' in Nixon|Able was I, ere I saw Elba!|ab|a|''|Hello, World!", cases, "|")
    for (k in cases) is_pal(cases[k])
}
EOF
awk -f <tmp>
